// func compressChunks8AVX512(cvs *[8][8]uint32, buf *[8192]byte, key *[8]uint32, counter uint64, flags uint32)
// Requires: AVX, AVX2, AVX512F, AVX512VL
TEXT ·compressChunks8AVX512(SB), NOSPLIT, $128-36
	MOVQ cvs+0(FP), AX
	MOVQ buf+8(FP), CX
	MOVQ key+16(FP), DX

	// Initialize counter
	VPBROADCASTD counter+24(FP), Y0
	VPADDD       seq<>+0(SB), Y0, Y0
	VPCMPUD      $0x01, seq<>+0(SB), Y0, K1
	VPBROADCASTD counter+28(FP), Y2
	VPADDD.BCST  seq<>+4(SB), Y2, K1, Y2
	VMOVDQU32    Y0, (SP)
	VMOVDQU32    Y2, 32(SP)

	// Initialize flags
	VPBROADCASTD flags+32(FP), Z0
	VMOVDQU32    Z0, 64(SP)
	ORL          $0x01, 64(SP)
	ORL          $0x02, 124(SP)

	// Load key
	VPBROADCASTD (DX), Y0
	VPBROADCASTD 4(DX), Y2
	VPBROADCASTD 8(DX), Y4
	VPBROADCASTD 12(DX), Y6
	VPBROADCASTD 16(DX), Y8
	VPBROADCASTD 20(DX), Y10
	VPBROADCASTD 24(DX), Y12
	VPBROADCASTD 28(DX), Y14

	// Loop index
	XORQ DX, DX

compressChunks8AVX512_loop:
	// Load transposed block
	VMOVDQU32    (CX), X16
	VINSERTI32X4 $0x01, 4096(CX), Y16, Y16
	VMOVDQU32    1024(CX), X18
	VINSERTI32X4 $0x01, 5120(CX), Y18, Y18
	VMOVDQU32    2048(CX), X20
	VINSERTI32X4 $0x01, 6144(CX), Y20, Y20
	VMOVDQU32    3072(CX), X22
