	VPUNPCKLDQ   Y18, Y16, Y24
	VPUNPCKHDQ   Y18, Y16, Y26
	VPUNPCKLDQ   Y22, Y20, Y28
	VPUNPCKHDQ   Y22, Y20, Y30
	VPUNPCKLQDQ  Y28, Y24, Y1
	VPUNPCKHQDQ  Y28, Y24, Y3
	VPUNPCKLQDQ  Y30, Y26, Y5
	VPUNPCKHQDQ  Y30, Y26, Y7
	VMOVDQU32    16(CX), X16
	VINSERTI32X4 $0x01, 4112(CX), Y16, Y16
