	VINSERTI32X4 $0x01, 5136(CX), Y18, Y18
	VMOVDQU32    2064(CX), X20
	VINSERTI32X4 $0x01, 6160(CX), Y20, Y20
	VMOVDQU32    3088(CX), X22
	VINSERTI32X4 $0x01, 7184(CX), Y22, Y22
	VPUNPCKLDQ   Y18, Y16, Y24
	VPUNPCKHDQ   Y18, Y16, Y26
	VPUNPCKLDQ   Y22, Y20, Y28
	VPUNPCKHDQ   Y22, Y20, Y30
	VPUNPCKLQDQ  Y28, Y24, Y9
	VPUNPCKHQDQ  Y28, Y24, Y11
	VPUNPCKLQDQ  Y30, Y26, Y13
	VPUNPCKHQDQ  Y30, Y26, Y15
	VMOVDQU32    32(CX), X16
	VINSERTI32X4 $0x01, 4128(CX), Y16, Y16
	VMOVDQU32    1056(CX), X18
	VINSERTI32X4 $0x01, 5152(CX), Y18, Y18
	VMOVDQU32    2080(CX), X20
	VINSERTI32X4 $0x01, 6176(CX), Y20, Y20
	VMOVDQU32    3104(CX), X22
	VINSERTI32X4 $0x01, 7200(CX), Y22, Y22
	VPUNPCKLDQ   Y18, Y16, Y24
	VPUNPCKHDQ   Y18, Y16, Y26
