	VINSERTI32X4 $0x01, 4144(CX), Y16, Y16
	VMOVDQU32    1072(CX), X18
	VINSERTI32X4 $0x01, 5168(CX), Y18, Y18
	VMOVDQU32    2096(CX), X20
	VINSERTI32X4 $0x01, 6192(CX), Y20, Y20
	VMOVDQU32    3120(CX), X22
